using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;
namespace CodexOutTransfer {
public static class OutRidgeCheck {
const string W="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/",O="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/outputs/";
static string Path(Transform t){return t.parent?Path(t.parent)+"/"+t.name:t.name;}
static void Capture(Camera c,string n){typeof(OutSceneTransfer).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{c,O+n});}
[MenuItem("Tools/Out Scene Transfer/Identify Hill Shadow Caster")]
public static void Shadows(){var b=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");var c=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");var renderers=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(false)).Where(r=>r.enabled).ToArray();foreach(string kind in new[]{"grass","ground","trees"}){var rs=renderers.Where(r=>kind=="grass"?r.sharedMaterials.Any(m=>m&&m.shader&&(m.shader.name.Contains("WorldGrass")||m.shader.name.Contains("PlatformGrass")||m.shader.name.Contains("DistantHillGrass"))):kind=="ground"?r.name.Contains("Ground_Mound"):r.sharedMaterials.Any(m=>m&&m.shader&&m.shader.name=="Codex/PainterlyMeadow/Foliage")).ToArray();var modes=rs.Select(r=>r.shadowCastingMode).ToArray();try{for(int i=0;i<rs.Length;i++)rs[i].shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;Capture(c,"Out_ridge_no_"+kind+"_casting.png");b.AppendLine(kind+" count="+rs.Length+" originallyCasting="+modes.Count(m=>m!=UnityEngine.Rendering.ShadowCastingMode.Off));}finally{for(int i=0;i<rs.Length;i++)rs[i].shadowCastingMode=modes[i];}}
b.AppendLine("restored=True");}catch(Exception e){b.AppendLine(e.ToString());}File.WriteAllText(W+"out_ridge_casters.txt",b.ToString());}
[MenuItem("Tools/Out Scene Transfer/Inspect Terrain Shadow Overlap")]
public static void TerrainShadows(){var b=new StringBuilder();try{var s=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");var c=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");var terrain=Terrain.activeTerrains;foreach(var t in terrain){b.AppendLine("terrain="+Path(t.transform)+" pos="+t.transform.position+" shadows="+t.shadowCastingMode+" draw="+t.drawHeightmap);var mode=t.shadowCastingMode;try{t.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;Capture(c,"Out_ridge_no_terrain_shadow.png");}finally{t.shadowCastingMode=mode;}}
var rs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(false)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.shadowCastingMode!=UnityEngine.Rendering.ShadowCastingMode.Off&&!r.name.Contains("Ground_Mound")&&!r.sharedMaterials.Any(m=>m&&m.shader&&m.shader.name=="Codex/PainterlyMeadow/Foliage")).ToArray();b.AppendLine("otherCasters="+rs.Length);foreach(var r in rs.Where(r=>r.shadowCastingMode==UnityEngine.Rendering.ShadowCastingMode.ShadowsOnly||r.bounds.size.magnitude>20))b.AppendLine("caster="+Path(r.transform)+" mode="+r.shadowCastingMode+" bounds="+r.bounds);var modes=rs.Select(r=>r.shadowCastingMode).ToArray();try{for(int i=0;i<rs.Length;i++)rs[i].shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;Capture(c,"Out_ridge_no_other_casters.png");}finally{for(int i=0;i<rs.Length;i++)rs[i].shadowCastingMode=modes[i];}b.AppendLine("restored=True");}catch(Exception e){b.AppendLine(e.ToString());}File.WriteAllText(W+"out_ridge_terrain.txt",b.ToString());}
[MenuItem("Tools/Out Scene Transfer/Inspect Hill Ridge Seam")]
public static void Inspect(){var b=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");var camera=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");var meshes=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(false)).Where(r=>r.enabled&&r.GetComponent<MeshFilter>()?.sharedMesh).ToArray();var intersect=typeof(HandleUtility).GetMethod("IntersectRayMesh",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);b.AppendLine("camera="+camera.transform.position+" rot="+camera.transform.eulerAngles+" fov="+camera.fieldOfView+" aspect="+camera.aspect+" intersectMethod="+intersect);
float aspect=camera.aspect;try{camera.aspect=16f/9;foreach(float x in new[]{.42f,.55f,.68f,.82f,.95f})foreach(float y in new[]{.42f,.50f,.57f,.62f}){var ray=camera.ViewportPointToRay(new Vector3(x,y,0));var hits=new System.Collections.Generic.List<Tuple<float,string>>();foreach(var r in meshes){float d;if(!r.bounds.IntersectRay(ray,out d))continue;if(intersect!=null){object[] args={ray,r.GetComponent<MeshFilter>().sharedMesh,r.localToWorldMatrix,new RaycastHit()};if((bool)intersect.Invoke(null,args)){var h=(RaycastHit)args[3];hits.Add(Tuple.Create(h.distance,Path(r.transform)+" shader="+r.sharedMaterial?.shader?.name+" mat="+AssetDatabase.GetAssetPath(r.sharedMaterial)+" @"+h.point));}}}b.AppendLine("screen="+x+","+y+" => "+string.Join(" | ",hits.OrderBy(t=>t.Item1).Take(3).Select(t=>t.Item1+" "+t.Item2)));}}finally{camera.aspect=aspect;}
var sun=RenderSettings.sun;b.AppendLine("sun="+sun.name+" cookie="+AssetDatabase.GetAssetPath(sun.cookie)+" shadows="+sun.shadows);var shadows=sun.shadows;try{sun.shadows=LightShadows.None;Capture(camera,"Out_ridge_without_cast_shadows.png");}finally{sun.shadows=shadows;}
var air=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeadowAtmosphere>(false)).FirstOrDefault();var active=air?air.animateClouds:false;var cookie=sun.cookie;try{if(air)air.animateClouds=false;sun.cookie=null;Capture(camera,"Out_ridge_without_cookie.png");}finally{sun.cookie=cookie;if(air)air.animateClouds=active;}
Capture(camera,"Out_ridge_current.png");b.AppendLine("inspected=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_ridge_check.txt",b.ToString());}
}
}
